# Produce labels on sampled-index intervals so that "0->1" labels sampled frame 0.
# Estimate motion using the transform from sample i -> i+1, then assign it to interval i->i+1.
step_labels=[]  # length will be num_samples; step_labels[i] corresponds to interval i->i+1

for i in range(num_samples - 1):
    # estimate dx, dy, rot, scale from frames[i] -> frames[i+1]
    lbl=[]
    if abs(scale-1)>th_scale: lbl.append("Dolly In" if scale>1 else "Dolly Out")
    if abs(rot)>th_rot: lbl.append("Roll Right" if rot>0 else "Roll Left")
    if abs(dx)>th_trans and abs(dx)>=abs(dy): lbl.append("Pan Left" if dx>0 else "Pan Right")
    if abs(dy)>th_trans and abs(dy)>abs(dx): lbl.append("Tilt Up" if dy>0 else "Tilt Down")
    if not lbl: lbl.append("Stay")
    step_labels.append(lbl)

# Last sampled frame has no forward pair; use a safe default to ensure full coverage.
step_labels.append(["Stay"])
